#include "camera.h"
#include "cam_plan.h"
#include "board.h"
#include "pio_alloc.h"
#include "power_fsm.h"
#include "safe_state.h"

#include "hardware/clocks.h"
#include "hardware/gpio.h"
#include "hardware/pio.h"
#include "pico/stdlib.h"

#include <string.h>

#include "cam_handshake.pio.h"   // generated by pico_generate_pio_header()

#define CAM_PIO  PIO_BLK_CAMERA
#define CAM_SM   PIO_SM_CAMERA

static bool      s_inited;
static bool      s_active;       // the state machine is running a handshake
static unsigned  s_offset;
static uint64_t  s_deadline_us;  // the CPU's backstop for this handshake
static cam_run_t s_run;

// ---------------------------------------------------------------------------
// Pin ownership, as strobe.c does it for GPIO25: GPIO10 is SIO driven low
// except while a handshake runs, and every exit path puts it back BEFORE it
// touches the state machine. The SIO level and direction are written before the
// function switch, so the pad sees nothing but low during it. The program drops
// the trigger itself at the end of every handshake; this is the backstop.
// ---------------------------------------------------------------------------
static void trigger_sio_low(void) {
    gpio_put(PIN_CAM_TRIGGER, 0);
    gpio_set_dir(PIN_CAM_TRIGGER, GPIO_OUT);
    gpio_set_function(PIN_CAM_TRIGGER, GPIO_FUNC_SIO);
}

static void engine_reset(void) {
    trigger_sio_low();
    pio_sm_set_enabled(CAM_PIO, CAM_SM, false);
    pio_sm_clear_fifos(CAM_PIO, CAM_SM);
    pio_sm_restart(CAM_PIO, CAM_SM);
    pio_sm_exec(CAM_PIO, CAM_SM, pio_encode_jmp(s_offset));
    s_active = false;
}

void camera_init(void) {
    // pio_alloc_init() set this block's GPIOBASE to 0, so GPIO8/9/10 are in range.
    hard_assert(pio_get_gpio_base(CAM_PIO) == PIO_BASE_CAMERA);
    pio_sm_claim(CAM_PIO, CAM_SM);
    s_offset = (unsigned)pio_add_program(CAM_PIO, &cam_handshake_program);   // panics if no room
    cam_handshake_program_init(CAM_PIO, CAM_SM, s_offset, PIN_CAM_TRIGGER,
                               PIN_CAM_STROBE_0, PIN_CAM_STROBE_1);
    // The PIO reads the strobe inputs through their pads' input buffers, which
    // safe_state_init() left enabled (inputs with pull-downs). Nothing else to do.
    engine_reset();
    s_inited = true;
}

void camera_safe_off(void) {
    trigger_sio_low();               // first, whatever else is true
    if (!s_inited) return;
    bool was = s_active;
    engine_reset();
    if (was) {
        s_run.state = CAM_RUN_ABORTED;
        s_run.trigger_low_after = !gpio_get(PIN_CAM_TRIGGER);
    }
}

const char *camera_start_text(cam_start_t s) {
    switch (s) {
        case CAM_START_OK:           return "ok";
        case CAM_START_NOT_INIT:     return "the camera engine is not initialised";
        case CAM_START_BUSY:         return "a handshake is already running";
        case CAM_START_RAIL:         return "the +5 V rail is not up ('on' first): the trigger is never driven without it";
        case CAM_START_FAULT:        return "a fault is latched ('fault' to read it, 'fault clear' to clear it)";
        case CAM_START_TRIGGER_HIGH: return "D_Cam_Trigger (GPIO10) is already high -- 'gpio 10 0' first";
        case CAM_START_STROBES_HIGH: return "a Cam_Strobe input (GPIO8/9) reads HIGH before the trigger: a camera already exposing, or a wiring fault -- the handshake would complete at once";
    }
    return "?";
}

const char *camera_run_text(cam_run_state_t s) {
    switch (s) {
        case CAM_RUN_NONE:      return "none since boot";
        case CAM_RUN_WAITING:   return "waiting for both strobes";
        case CAM_RUN_READY:     return "both strobes seen; trigger held";
        case CAM_RUN_DONE:      return "done: trigger released after the hold";
        case CAM_RUN_TIMEOUT:   return "TIMEOUT: strobes not seen, trigger dropped, no FIRE";
        case CAM_RUN_BAD_WORD:  return "STOPPED: the engine sent a word it cannot produce";
        case CAM_RUN_NO_REPORT: return "STOPPED: the engine did not report by its own end time";
        case CAM_RUN_ABORTED:   return "ABORTED: the trigger was taken down mid-handshake (rail down or safe-off)";
    }
    return "?";
}

// The latest the program can still be running: a late FIRE at the end of the
// late window, then the whole hold. Plus CAM_ENGINE_MARGIN_US.
static uint64_t end_by_us(const cam_plan_t *p) {
    uint64_t cyc = (uint64_t)cam_timeout_release_cycles(p) + CAM_PIO_FIRE_LATE_CYCLES
                 + (uint64_t)CAM_PIO_LOOP_CYCLES * p->h + CAM_PIO_HOLD_RELEASE_CYCLES;
    return cyc * 1000000u / p->sys_hz + 1u + CAM_ENGINE_MARGIN_US;
}

cam_start_t camera_start(const cam_plan_t *p) {
    if (!s_inited) return CAM_START_NOT_INIT;
    if (s_active)  return CAM_START_BUSY;
    if (!power_rails_ready()) return CAM_START_RAIL;
    if (fault_current() != FAULT_NONE) return CAM_START_FAULT;
    if (gpio_get(PIN_CAM_TRIGGER) || gpio_get_out_level(PIN_CAM_TRIGGER)) return CAM_START_TRIGGER_HIGH;
    if (gpio_get(PIN_CAM_STROBE_0) || gpio_get(PIN_CAM_STROBE_1)) return CAM_START_STROBES_HIGH;

    // Known state, then this SM's own output latch low and enabled while the pad
    // is still SIO low. Only then does the pad change hands.
    engine_reset();
    const uint32_t trig = 1u << PIN_CAM_TRIGGER;
    pio_sm_set_pins_with_mask(CAM_PIO, CAM_SM, 0u, trig);
    pio_sm_set_pindirs_with_mask(CAM_PIO, CAM_SM, trig, trig);

    // The three counts, with the state machine stopped. The TX FIFO is 4 deep.
    pio_sm_put(CAM_PIO, CAM_SM, p->d);
    pio_sm_put(CAM_PIO, CAM_SM, p->t);
    pio_sm_put(CAM_PIO, CAM_SM, p->h);

    memset(&s_run, 0, sizeof s_run);
    s_run.valid = true;
    s_run.state = CAM_RUN_WAITING;
    s_run.plan  = *p;

    pio_gpio_init(CAM_PIO, PIN_CAM_TRIGGER);
    s_active = true;
    s_run.t_start_us = time_us_64();
    s_deadline_us    = s_run.t_start_us + end_by_us(p);
    pio_sm_set_enabled(CAM_PIO, CAM_SM, true);    // pull, pull, trigger high
    return CAM_START_OK;
}

cam_start_t camera_manual_trigger(bool high) {
    if (!high) {
        camera_safe_off();                       // always: the safe direction
        return CAM_START_OK;
    }
    if (!s_inited) return CAM_START_NOT_INIT;
    if (s_active)  return CAM_START_BUSY;
    if (!power_rails_ready()) return CAM_START_RAIL;
    if (fault_current() != FAULT_NONE) return CAM_START_FAULT;
    // SIO, driven high: the level first, then the direction, then the function,
    // so the pad never shows anything else during the switch.
    gpio_put(PIN_CAM_TRIGGER, 1);
    gpio_set_dir(PIN_CAM_TRIGGER, GPIO_OUT);
    gpio_set_function(PIN_CAM_TRIGGER, GPIO_FUNC_SIO);
    return CAM_START_OK;
}

// Over: the engine has already dropped the trigger (END, TIMEOUT), or must be
// stopped. Either way the pad goes back to SIO low before the state machine is
// touched, and the SM never pulls again.
static void finish(cam_run_state_t st) {
    engine_reset();
    s_run.state = st;
    s_run.trigger_low_after = !gpio_get(PIN_CAM_TRIGGER);
}

static void take_word(uint32_t w) {
    uint32_t t = (uint32_t)(time_us_64() - s_run.t_start_us);
    if (s_run.words == 0u) {
        s_run.words = 1u;
        s_run.word0 = w;
        s_run.cpu_ready_us = t;
        s_run.res = cam_decode(w, &s_run.plan);
        switch (s_run.res.outcome) {
            case CAM_OUT_EARLY:
            case CAM_OUT_LATE:    s_run.state = CAM_RUN_READY; break;
            case CAM_OUT_TIMEOUT: s_run.cpu_end_us = t; finish(CAM_RUN_TIMEOUT); break;
            default:              finish(CAM_RUN_BAD_WORD); break;
        }
        return;
    }
    s_run.words = 2u;
    s_run.word1 = w;
    s_run.cpu_end_us = t;
    finish(w == CAM_WORD_END ? CAM_RUN_DONE : CAM_RUN_BAD_WORD);
}

cam_run_state_t camera_poll(cam_run_t *out) {
    if (s_active) {
        while (s_active && !pio_sm_is_rx_fifo_empty(CAM_PIO, CAM_SM))
            take_word(pio_sm_get(CAM_PIO, CAM_SM));
        if (s_active && time_us_64() > s_deadline_us) finish(CAM_RUN_NO_REPORT);
    }
    if (out) *out = s_run;
    return s_run.state;
}

bool camera_busy(void) { return s_active; }

const cam_run_t *camera_last(void) { return &s_run; }

void camera_info(camera_info_t *o) {
    memset(o, 0, sizeof(*o));
    o->inited          = s_inited;
    o->busy            = s_active;
    o->pio_index       = pio_get_index(CAM_PIO);
    o->sm              = CAM_SM;
    o->offset          = s_offset;
    o->length          = cam_handshake_program.length;
    o->sm_enabled      = ((CAM_PIO->ctrl >> (PIO_CTRL_SM_ENABLE_LSB + CAM_SM)) & 1u) != 0u;
    o->pc              = pio_sm_get_pc(CAM_PIO, CAM_SM);
    o->tx_level        = pio_sm_get_tx_fifo_level(CAM_PIO, CAM_SM);
    o->rx_level        = pio_sm_get_rx_fifo_level(CAM_PIO, CAM_SM);
    o->trigger_pio     = gpio_get_function(PIN_CAM_TRIGGER) == (gpio_function_t)pio_get_funcsel(CAM_PIO);
    o->trigger_pad     = gpio_get(PIN_CAM_TRIGGER);
    o->trigger_out_sio = gpio_get_out_level(PIN_CAM_TRIGGER);
    o->strobe0_pad     = gpio_get(PIN_CAM_STROBE_0);
    o->strobe1_pad     = gpio_get(PIN_CAM_STROBE_1);
    o->fire_flag       = pio_interrupt_get(PIO_BLK_LOW, PIO_IRQ_CAM_FIRE);
    o->sys_hz          = clock_get_hz(clk_sys);
}

// Labels for the program's addresses, in cam_handshake.pio's order. The host
// tests check its encodings; this pins it at 29 instructions.
_Static_assert(sizeof cam_handshake_program_instructions / sizeof cam_handshake_program_instructions[0] == 29u,
               "cam_handshake.pio changed: update camera_pc_label()");

const char *camera_pc_label(unsigned pc) {
    static const char *const k[29] = {
        "load D", "load D", "load T", "trigger high",
        "poll", "poll", "poll", "poll", "poll",
        "first delay over", "timeout", "timeout", "timeout",
        "late window", "late window",
        "ready", "ready (late)", "ready (late)", "report",
        "first delay", "FIRE", "load H", "load H", "hold",
        "release", "release", "release",
        "ready (early)", "ready (early)",
    };
    unsigned rel = (pc - s_offset) & 31u;
    return rel < 29u ? k[rel] : "?";
}
